$:set -euo pipefail
node <<'NODE'
const fs=require('node:fs');
let s=fs.readFileSync('workspaces/programs/scratchpad/SRS.md','utf8');
if(!s.includes('**Specification:** TP-SRS-001, v1.0.0')||s.includes('**PC-01:**'))throw Error('Unexpected SRS revision');
s=s.replace('**Specification:** TP-SRS-001, v1.0.0','**Specification:** TP-SRS-001, v1.1.0');
s=s.replace('## Input contracts',String.raw"## Reusable program-control comment lifecycle

- **PC-01:** A program instance SHALL hold exclusive ownership of its designated **control-comment ID** only while its instance status is active. This ID SHALL NOT be conflated with a scratchpad's persistent **data-comment ID**.
- **PC-02:** Every allocation SHALL bind the control-comment ID to a unique instance ID and monotonically increasing generation number. The active binding SHALL be recorded in durable program-session state.
- **PC-03:** On explicit **completion** or **termination**, the program SHALL release the control-comment binding and mark the comment **available** for another instance.
- **PC-04:** A subsequent program instance SHALL be able to acquire an available control-comment ID and SHALL receive a **new instance ID and generation**, even when the numeric comment ID is reused.
- **PC-05:** Every mutating or session-scoped command SHALL verify the supplied control-comment ID, instance ID and generation against the current active binding. Superseded, completed or terminated instances SHALL be rejected.
- **PC-06:** Release SHALL be idempotent for the same already-ended instance and SHALL NOT release an active binding belonging to any other instance.
- **PC-07:** The control-comment lease store SHALL use an optimistic concurrency mechanism to avoid assigning one comment to multiple active instances. If UI comment rendering and lease state disagree, the lease state SHALL be authoritative, and the UI SHALL be repaired.
- **PC-08:** Ending a program instance SHALL NOT destroy, reassign, reset or rewrite the persistent scratchpad data comments produced by that instance.
- **PC-09:** A session SHALL remain active across multiple terminal commands and workflow runs until explicit completion, termination, or documented recovery of an abandoned instance. Completion of a single command SHALL NOT implicitly release the session.
- **PC-10:** The program SHALL return the control-comment ID, current instance ID, generation and session status at allocation, status checks and release.
- **PC-11:** A failed or interrupted program instance SHALL have a documented administrative recovery or termination operation that releases abandoned control comments safely without permitting stale commands to act after reassignment.

**Lifecycle:** available → assigned/active → completed or terminated → available → assigned to a different instance. The release event SHALL be retained as a durable transition record, although the control comment's visible menu can be replaced on reassignment.

**Control instance commands:** the scratchpad application's programInput SHALL accept \`{"operation":"start"}\`, \`{"operation":"complete","control_comment_id":<id>,"instance_id":<id>,"generation":<number>}\`, and \`{"operation":"terminate",...}\` in addition to its scratchpad data operations. All session-bound data operations SHALL include matching control identifiers.

**State authority:** \`workspaces/programs/sessions/state.json\` is the persisted control-comment assignment registry. Its GitHub file SHA is an optimistic update precondition. Control comments may render a program menu or a released-state notice, but neither the menu nor a terminal stdout receipt grants an active lease.

**Example transition:** Instance A owns control comment 123, generation 4; instance A completes. Registry marks 123 available. Instance B acquires comment 123 at generation 5. A command with A's instance ID and generation 4 fails with STALE_INSTANCE. The permanent scratchpad data comment created by A remains unchanged.

"+'
## Input contracts');
fs.writeFileSync('workspaces/programs/scratchpad/SRS.md',s);
let p=JSON.parse(fs.readFileSync('workspaces/programs/scratchpad/SRS.agent.json'));
if(p.version!=='1.0.0')throw Error('Unexpected projection revision');
p.version='1.1.0';p.source.revision='1.1.0';
p.requirements.push(...[{"id":"PC-01","behavior":"Exclusive control-comment ownership for active program instance, separate from permanent scratchpad data IDs"},{"id":"PC-02","behavior":"Unique instance ID, monotonically increasing lease generation, durable registry"},{"id":"PC-03","behavior":"Completion or termination immediately releases control-comment ownership"},{"id":"PC-04","behavior":"New instance may reuse released comment ID but receives new instance identity and generation"},{"id":"PC-05","behavior":"Stale instance commands rejected by instance ID/generation authorization"},{"id":"PC-06","behavior":"Idempotent release, no cross-instance release"},{"id":"PC-07","behavior":"Atomic compare-and-swap registration; registry authoritative over rendered UI"},{"id":"PC-08","behavior":"Scratchpad data comments retained unchanged after control release"},{"id":"PC-09","behavior":"Session remains active across workflow runs until program end/recovery"},{"id":"PC-10","behavior":"Return IDs, generation and status"},{"id":"PC-11","behavior":"Administrative recovery of orphaned sessions without authorizing stale commands"}]);
p.architecture.control_comment_lease={state_path:'workspaces/programs/sessions/state.json',scope:'Terminals Issue #5 control comments',status:['active','available'],reusable_comment_id:true,instance_generation:'monotonically_increasing',lifetime:'program instance, not single command',release_on:['complete','terminate','administrative_recovery'],data_comments:'unchanged by release'};
p.data.control_session={control_comment_id:'GitHub issue comment ID',instance_id:'opaque unique string',generation:'integer incremented per reuse',status:'active or available',persisted_registry:'workspaces/programs/sessions/state.json'};
p.acceptance.push('completion releases program control comment without deleting scratchpad data','termination releases program control comment','next instance can acquire identical comment ID with new instance identity/generation','stale previous instance cannot operate after reuse','concurrent acquisitions cannot reserve one comment twice');
fs.writeFileSync('workspaces/programs/scratchpad/SRS.agent.json',JSON.stringify(p,null,2)+'
');
console.log(JSON.stringify({SRS:'1.1.0',projection:'1.1.0',requirements:p.requirements.length}));
NODE
for file in workspaces/programs/scratchpad/SRS.md workspaces/programs/scratchpad/SRS.agent.json; do
  current="$(gh api "repos/BestNameYet/Terminals/contents/$file" --jq .sha)"
  commit="$(gh api --method PUT "repos/BestNameYet/Terminals/contents/$file" -f sha="$current" -f message="Version scratchpad SRS 1.1.0: reusable control comment session leases" -f content="$(base64 -w0 "$file")" --jq .commit.sha)"
  gh api "repos/BestNameYet/Terminals/contents/$file" --jq .content | tr -d '\n' | base64 -d > /tmp/srs-readback
  cmp "$file" /tmp/srs-readback
  printf 'VERIFIED_FILE=%s COMMIT=%s
' "$file" "$commit"
done
